const now = new Date();
const daysAgo = 7;
const sinceDate = new Date(now.getTime() - (daysAgo * 24 * 60 * 60 * 1000));
return [{
  json: {
    since_iso: sinceDate.toISOString(),
    now_iso: now.toISOString(),
    time_window_label: `${sinceDate.toISOString().slice(0, 10)} to ${now.toISOString().slice(0, 10)}`
  }
}];

const config = $('Configuration & Environment').first().json;
const windowMeta = $('Calculate 7-Day Window').first().json;
const sinceDate = new Date(windowMeta.since_iso);

// 1. Process Commits
const commitItems = $('Fetch Weekly Commits').all();
const commitList = commitItems.map(item => {
  const c = item.json;
  return `- ${c.commit?.message?.split('\n')[0]} (by ${c.commit?.author?.name || 'unknown'})`;
}).slice(0, 40);

// 2. Process Closed Issues
const issueItems = $('Fetch Closed Issues').all();
const closedIssues = issueItems
  .filter(item => !item.json.pull_request)
  .map(item => `- #${item.json.number}: ${item.json.title}`)
  .slice(0, 30);

// 3. Process Merged PRs
const prItems = $('Fetch Closed PRs').all();
const mergedPRs = prItems
  .filter(item => item.json.merged_at && new Date(item.json.merged_at) >= sinceDate)
  .map(item => `- PR #${item.json.number}: ${item.json.title} (merged by ${item.json.user?.login || 'contributor'})`)
  .slice(0, 30);

const isFrench = (config.language || '').toUpperCase() === 'FR';

const systemInstruction = isFrench
  ? 'Tu es un directeur technique chevronné qui rédige un récapitulatif narratif hebdomadaire clair et stimulant pour l\'équipe d\'ingénierie.'
  : 'You are a veteran engineering director writing an engaging, structured weekly narrative executive summary for the product and development team.';

const promptContent = isFrench
  ? `Génère le résumé de la semaine pour le dépôt ${config.github_repo_owner}/${config.github_repo_name} (${windowMeta.time_window_label}):\n\n` +
    `### Données d\'activité:\n` +
    `- Commits récents (${commitList.length}):\n${commitList.join('\n') || 'Aucun commit'}\n\n` +
    `- PRs fusionnées (${mergedPRs.length}):\n${mergedPRs.join('\n') || 'Aucune PR'}\n\n` +
    `- Tickets résolus (${closedIssues.length}):\n${closedIssues.join('\n') || 'Aucun ticket'}\n\n` +
    `Structure ta réponse avec:\n1. 🚀 Points saillants & réalisations clés\n2. 🛠️ Fonctionnalités & correctifs livrés\n3. 🎯 Focus et momentum pour la semaine prochaine.`
  : `Generate a narrative weekly engineering summary for ${config.github_repo_owner}/${config.github_repo_name} (${windowMeta.time_window_label}):\n\n` +
    `### Activity Data:\n` +
    `- Recent Commits (${commitList.length}):\n${commitList.join('\n') || 'No commits'}\n\n` +
    `- Merged PRs (${mergedPRs.length}):\n${mergedPRs.join('\n') || 'No merged PRs'}\n\n` +
    `- Closed Issues (${closedIssues.length}):\n${closedIssues.join('\n') || 'No closed issues'}\n\n` +
    `Structure your output with:\n1. 🚀 Key Highlights & Major Milestones\n2. 🛠️ Shipped Features & Bug Fixes\n3. 🎯 Next Week's Momentum & Engineering Focus.`;

return [{
  json: {
    system: systemInstruction,
    prompt: promptContent,
    repo: `${config.github_repo_owner}/${config.github_repo_name}`,
    language: config.language,
    destination_channel: config.destination_channel,
    webhook_url: config.webhook_url,
    stats: {
      commits: commitList.length,
      prs_merged: mergedPRs.length,
      issues_closed: closedIssues.length
    }
  }
}];

const claudeResponse = $input.first().json;
const aggregateNode = $('Aggregate Activity & Form Prompt').first().json;
const contentText = claudeResponse.content?.[0]?.text || 'No summary generated.';
const channel = (aggregateNode.destination_channel || 'discord').toLowerCase();

let webhookPayload = {};
if (channel === 'slack') {
  webhookPayload = {
    text: `*Weekly Engineering Summary: ${aggregateNode.repo}*\n\n${contentText}`,
    blocks: [
      {
        type: 'header',
        text: { type: 'plain_text', text: `Weekly Summary: ${aggregateNode.repo}`, emoji: true }
      },
      {
        type: 'section',
        text: { type: 'mrkdwn', text: contentText }
      },
      {
        type: 'context',
        elements: [
          { type: 'mrkdwn', text: `📊 Commits: *${aggregateNode.stats.commits}* | Merged PRs: *${aggregateNode.stats.prs_merged}* | Issues Closed: *${aggregateNode.stats.issues_closed}* | Generated with Claude Sonnet` }
        ]
      }
    ]
  };
} else {
  // Discord default
  webhookPayload = {
    username: 'Claude Weekly Dev Bot',
    avatar_url: 'https://raw.githubusercontent.com/anthropics/anthropic-cookbook/main/misc/claude_icon.png',
    content: `📢 **Weekly Engineering Summary: ${aggregateNode.repo}**\n\n${contentText.slice(0, 1900)}`
  };
}

return [{
  json: {
    webhook_url: aggregateNode.webhook_url,
    channel: channel,
    payload: webhookPayload,
    summary_markdown: contentText
  }
}];
